    17	import java.time.YearMonth;
    18	import org.junit.jupiter.api.AfterEach;
    19	import org.junit.jupiter.api.BeforeEach;
    20	import org.junit.jupiter.api.Test;
    21	
    22	class ReportsTest {
    23	
    24	    private final EmptyDatabase database = new EmptyDatabase();
    25	    private final Rooms rooms = new Rooms(database.dataSource());
    26	    private final ReservationStore store = new ReservationStore(database.dataSource());
    27	    private final ReservationService service = new ReservationService(
    28	            rooms, store, new PriceCalculator(), new EmailSender(new SentMessages(database.dataSource())));
    29	
    30	    private Reservation book(int roomNumber, String checkIn, String checkOut, RatePlan plan) {
    31	        Guest guest = new Guest("Bruno Lima", "bruno@example.com", "987.654.321-00");
    32	        return service.create(new NewReservation(
    33	                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), 1, plan));
    34	    }
    35	
    36	    @AfterEach
    37	    void closeDatabase() {
    38	        database.close();
    39	    }
    40	
    41	    @BeforeEach
    42	    void someReservations() {
    43	        Reservation april = book(201, "2027-04-01", "2027-04-03", RatePlan.STANDARD);
    44	        Reservation lateMarch = book(101, "2027-03-30", "2027-04-02", RatePlan.NON_REFUNDABLE);
    45	        Reservation suite = book(301, "2027-04-02", "2027-04-04", RatePlan.STANDARD);
    46	        book(102, "2027-04-01", "2027-04-05", RatePlan.STANDARD); // never paid
    47	        Reservation cancelled = book(202, "2027-04-01", "2027-04-02", RatePlan.STANDARD);
    48	        service.confirm(april.id());
    49	        service.confirm(lateMarch.id());
    50	        service.confirm(suite.id());
    51	        service.checkIn(suite.id());
    52	        service.confirm(cancelled.id());
    53	        service.cancel(cancelled.id());
    54	    }
    55	
    56	    @Test
    57	    void occupancyListsThePaidReservationsCoveringTheNight() {
    58	        String csv = new OccupancyReport(rooms, store).generate(LocalDate.of(2027, 4, 1));
    59	
    60	        assertEquals("""
    61	                room,type,reservation,guest,check_in,check_out
    62	                101,STANDARD,2,Bruno Lima,2027-03-30,2027-04-02
    63	                201,DELUXE,1,Bruno Lima,2027-04-01,2027-04-03
    64	                total,2/5
    65	                """, csv);
    66	    }
    67	
    68	    @Test
    69	    void theCheckOutNightIsNotOccupied() {
    70	        String csv = new OccupancyReport(rooms, store).generate(LocalDate.of(2027, 4, 3));
    71	
    72	        assertEquals("""
    73	                room,type,reservation,guest,check_in,check_out
    74	                301,SUITE,3,Bruno Lima,2027-04-02,2027-04-04
    75	                total,1/5
    76	                """, csv);
    77	    }
    78	
    79	    @Test
    80	    void guestNameWithCommaIsReplacedWithSpace() {
    81	        Guest guest = new Guest("Silva, Ana Paula", "ana@example.com", "123.456.789-00");
    82	        Reservation reservation = service.create(new NewReservation(
    83	                101, guest, LocalDate.parse("2027-05-01"), LocalDate.parse("2027-05-02"), 1, RatePlan.STANDARD));
    84	        service.confirm(reservation.id());
    85	
    86	        String csv = new OccupancyReport(rooms, store).generate(LocalDate.of(2027, 5, 1));
    87	
    88	        assertEquals("""
    89	                room,type,reservation,guest,check_in,check_out
    90	                101,STANDARD,6,Silva  Ana Paula,2027-05-01,2027-05-02
    91	                total,1/5
    92	                """, csv);
    93	    }
    94	
    95	    @Test
    96	    void revenueSumsTheMoneyKeptFromReservationsStartingInTheMonth() {
    97	        String csv = new RevenueReport(store).generate(YearMonth.of(2027, 4));
